(4353123, 628038, 81382, '<td valign="top">Clever title, nice and simple compositions, I just feel the texture on the glass could be a bit sharper</td>', 'Clever title, nice and simple compositions, I just feel the texture on the glass could be a bit sharper', '2008-01-02 08:31:44.000000', NULL, 1),
(4353128, 626552, 81382, '<td valign="top">Obviously without the title, it wouldn''t be related to the challange, even with the title it is pushing the theme a bit too hard. The lighting on the figure is nice.</td>', 'Obviously without the title, it wouldn''t be related to the challange, even with the title it is pushing the theme a bit too hard. The lighting on the figure is nice.', '2008-01-02 08:33:26.000000', NULL, 1),
(4353132, 628147, 81382, '<td valign="top">Lovely warm tones but could have been expanded via levels or curves to use more of the top end for increased contrast. I feel this could be sharper, perhaps this is due to the resize for submission - I always do a final USM (100, 0.5, 0) after the resize</td>', 'Lovely warm tones but could have been expanded via levels or curves to use more of the top end for increased contrast. I feel this could be sharper, perhaps this is due to the resize for submission - I always do a final USM (100, 0.5, 0) after the resize', '2008-01-02 08:35:35.000000', NULL, 1),
(4353136, 628181, 81382, '<td valign="top">The lighting on the face is perhaps not the most flattering as it has made the skin quite textured and shiny in places. You''ve done well to get the sharpness on the leading eye given the low light conditions</td>', 'The lighting on the face is perhaps not the most flattering as it has made the skin quite textured and shiny in places. You''ve done well to get the sharpness on the leading eye given the low light conditions', '2008-01-02 08:37:09.000000', NULL, 1),
(4353139, 627887, 81382, '<td valign="top">On the one hand, its nice to see something other than a candle, but this is perhaps pushing the competition brief a little hard.</td>', 'On the one hand, its nice to see something other than a candle, but this is perhaps pushing the competition brief a little hard.', '2008-01-02 08:38:34.000000', NULL, 1),
(4353147, 628100, 81382, '<td valign="top">As I''ve commented on others so far, a recurring theme seems to be sharpness. I understand that in a lot of cases, low light forces a long shutter and so the flames are blurred, and mostly this is very artistic and a good thing, but it needs to be offset by a sharp focal point. If the shape of the heart was a lot sharper then it would complement the flames more effectively.</td>', 'As I''ve commented on others so far, a recurring theme seems to be sharpness. I understand that in a lot of cases, low light forces a long shutter and so the flames are blurred, and mostly this is very artistic and a good thing, but it needs to be offset by a sharp focal point. If the shape of the heart was a lot sharper then it would complement the flames more effectively.', '2008-01-02 08:41:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4353149, 628222, 88010, '<td valign="top">Excellent attention to detail and focusing.</td>', 'Excellent attention to detail and focusing.', '2008-01-02 08:43:00.000000', NULL, 1),
(4353150, 627031, 88010, '<td valign="top">DMC But nice focus and nice shot.</td>', 'DMC But nice focus and nice shot.', '2008-01-02 08:43:29.000000', NULL, 1),
(4353152, 628001, 88010, '<td valign="top">Nice composition, wish I had thought of that.</td>', 'Nice composition, wish I had thought of that.', '2008-01-02 08:43:54.000000', NULL, 1),
(4353155, 626722, 81382, '<td valign="top">Harsh lighting in the bottom of the frame. Fairy easy difficulty factor and so I can''t see this scoring particularly highly I''m afraid. Perhaps a more angled, abstract composition where only a portion of the ring is visible, with really hard pushed contrast so that it appears as glowing rings on a perfectly black background might have been more effective.</td>', 'Harsh lighting in the bottom of the frame. Fairy easy difficulty factor and so I can''t see this scoring particularly highly I''m afraid. Perhaps a more angled, abstract composition where only a portion of the ring is visible, with really hard pushed contrast so that it appears as glowing rings on a perfectly black background might have been more effective.', '2008-01-02 08:44:27.000000', NULL, 1),
(4353158, 627061, 88010, '<td valign="top">Yep, the biggest fire we''ll ever actually see. But since that is the "subject" I think there is too much sky and not enough sun.</td>', 'Yep, the biggest fire we''ll ever actually see. But since that is the "subject" I think there is too much sky and not enough sun.', '2008-01-02 08:45:12.000000', NULL, 1),
(4353161, 627938, 88010, '<td valign="top">I know some people just love B&amp;W and I do too, but this subject doesn''t seem to POP from it. I think the hot yellow flames might have worked better.</td>', 'I know some people just love B&W and I do too, but this subject doesn''t seem to POP from it. I think the hot yellow flames might have worked better.', '2008-01-02 08:46:14.000000', NULL, 1),
(4353162, 626243, 81382, '<td valign="top">Difficult I do I know - but I feel its vital to get a sharp focal point in here somewhere to offset the blurred flames.</td>', 'Difficult I do I know - but I feel its vital to get a sharp focal point in here somewhere to offset the blurred flames.', '2008-01-02 08:46:16.000000', NULL, 1),
(4353163, 628038, 69374, '<td valign="top">Love the concept and the execution a clear winner in my book. Congratulations.</td>', 'Love the concept and the execution a clear winner in my book. Congratulations.', '2008-01-02 08:46:47.000000', NULL, 1),
(4353165, 626696, 88010, '<td valign="top">WQell I guess they left the door open for anything you deem as "fire". The lighting is a bit harsh.</td>', 'WQell I guess they left the door open for anything you deem as "fire". The lighting is a bit harsh.', '2008-01-02 08:47:53.000000', NULL, 1),
(4353166, 628320, 88010, '<td valign="top">It might be, but really from this view the light source could be a spot light shining in the evening. The pic just doesn''t say "fire" to me.</td>', 'It might be, but really from this view the light source could be a spot light shining in the evening. The pic just doesn''t say "fire" to me.', '2008-01-02 08:48:48.000000', NULL, 1),
(4353169, 628343, 88010, '<td valign="top">Well done. Nice colors and kept it simple, nothing there that isn''t needed.</td>', 'Well done. Nice colors and kept it simple, nothing there that isn''t needed.', '2008-01-02 08:49:49.000000', NULL, 1),
(4353173, 628367, 88010, '<td valign="top">I remember that show, but she always came out as smoke. Good color and nice lines.</td>', 'I remember that show, but she always came out as smoke. Good color and nice lines.', '2008-01-02 08:50:35.000000', NULL, 1),
(4353175, 627302, 81382, '<td valign="top">Unique subject and only really let down by the composition I feel - needs a slight cw rotation and the car is travelling into the left hand side so more empty space for the car to "move" into would normally work well except that here the flames are the main subject so its very difficult to know what to suggest. Perhaps a totally different viewpoint - wide angle, from the ground focusing on the back wheel with the flame trail only might have been simpler and more effective</td>', 'Unique subject and only really let down by the composition I feel - needs a slight cw rotation and the car is travelling into the left hand side so more empty space for the car to "move" into would normally work well except that here the flames are the main subject so its very difficult to know what to suggest. Perhaps a totally different viewpoint - wide angle, from the ground focusing on the back wheel with the flame trail only might have been simpler and more effective', '2008-01-02 08:50:47.000000', NULL, 1),
(4353176, 628082, 88010, '<td valign="top">Interesting choice, to only show a part of teh flame.</td>', 'Interesting choice, to only show a part of teh flame.', '2008-01-02 08:51:08.000000', NULL, 1),
(4353179, 628255, 88010, '<td valign="top">Nope, don''t hear it, but I see it. Good writing.</td>', 'Nope, don''t hear it, but I see it. Good writing.', '2008-01-02 08:51:53.000000', NULL, 1),
(4353181, 627127, 88010, '<td valign="top">One of those thought provoking shots. I guess the dish is full of water? Not really sure. Tone wise, nice B&amp;W conversion.</td>', 'One of those thought provoking shots. I guess the dish is full of water? Not really sure. Tone wise, nice B&W conversion.', '2008-01-02 08:53:00.000000', NULL, 1),
(4353184, 626684, 88010, '<td valign="top">DMC I see where the burn came from, but no "fire".</td>', 'DMC I see where the burn came from, but no "fire".', '2008-01-02 08:53:28.000000', NULL, 1),
(4353188, 626405, 88010, '<td valign="top">Yes, definitely a fire there somewhere, even if it''s thousands of miles away. Very nice colors and tones.</td>', 'Yes, definitely a fire there somewhere, even if it''s thousands of miles away. Very nice colors and tones.', '2008-01-02 08:54:20.000000', NULL, 1),
(4353191, 628337, 81382, '<td valign="top">Limited time frame to get the perfect shot and so this carries a relatively high difficulty. However, if only the red car was placed more in the frame, ideally a third in from the right (with room to move into the left hand side) just going over the flames would have been great to see. You have a fairly complex, irrelevent and distracting background, a tighter crop on the red car and the flames would have made for a more simple and dramatic shot</td>', 'Limited time frame to get the perfect shot and so this carries a relatively high difficulty. However, if only the red car was placed more in the frame, ideally a third in from the right (with room to move into the left hand side) just going over the flames would have been great to see. You have a fairly complex, irrelevent and distracting background, a tighter crop on the red car and the flames would have made for a more simple and dramatic shot', '2008-01-02 08:54:31.000000', NULL, 1),
(4353192, 628047, 88010, '<td valign="top">Nice photojournalism shot. Wish the falmes were better for the pic but glad they weren''t bigger for the people fighting the fire.</td>', 'Nice photojournalism shot. Wish the falmes were better for the pic but glad they weren''t bigger for the people fighting the fire.', '2008-01-02 08:55:07.000000', NULL, 1),
(4353193, 627119, 88010, '<td valign="top">nice landscape.</td>', 'nice landscape.', '2008-01-02 08:55:24.000000', NULL, 1),
(4353195, 628081, 55956, '<td valign="top">that lines on the background are a bit distracting</td>', 'that lines on the background are a bit distracting', '2008-01-02 08:55:46.000000', NULL, 1),
(4353196, 628037, 88010, '<td valign="top">Nice shot, I do wish it were a bit more clear though.</td>', 'Nice shot, I do wish it were a bit more clear though.', '2008-01-02 08:55:54.000000', NULL, 1),
(4353200, 628022, 88010, '<td valign="top">good job on the exposure. I wonder if you did any long exposure shots of this?</td>', 'good job on the exposure. I wonder if you did any long exposure shots of this?', '2008-01-02 08:56:52.000000', NULL, 1),
(4353206, 628117, 88010, '<td valign="top">Nice flame dance. But it does seem to not be level. I think it''s because the bar at left is not straight up and down.</td>', 'Nice flame dance. But it does seem to not be level. I think it''s because the bar at left is not straight up and down.', '2008-01-02 08:58:07.000000', NULL, 1),
(4353208, 627617, 88010, '<td valign="top">I wish I could see the colors. B&amp;W just doesn''t flatter the pic.</td>', 'I wish I could see the colors. B&W just doesn''t flatter the pic.', '2008-01-02 08:58:51.000000', NULL, 1),
