(4353217, 626977, 88010, '<td valign="top">Yes and it looks HOT.</td>', 'Yes and it looks HOT.', '2008-01-02 09:01:30.000000', NULL, 1),
(4353220, 626730, 88010, '<td valign="top">Nice lines used here. A little grainy. But it has a nice warm feel to it.</td>', 'Nice lines used here. A little grainy. But it has a nice warm feel to it.', '2008-01-02 09:02:27.000000', NULL, 1),
