(4355639, 626243, 85886, '<td valign="top">Would be much better if it was in focus.</td>', 'Would be much better if it was in focus.', '2008-01-02 22:03:10.000000', NULL, 1),
(4355661, 627159, 85886, '<td valign="top">An interesting idea but it might work better if the background had some more colour or brightness about it</td>', 'An interesting idea but it might work better if the background had some more colour or brightness about it', '2008-01-02 22:06:13.000000', NULL, 1),
(4355668, 628441, 85886, '<td valign="top">Gorgeous colours and lovely shapes - a really strong image</td>', 'Gorgeous colours and lovely shapes - a really strong image', '2008-01-02 22:07:25.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4355708, 627302, 85886, '<td valign="top">Fantastic idea!!!</td>', 'Fantastic idea!!!', '2008-01-02 22:16:08.000000', NULL, 1),
(4355712, 628038, 85886, '<td valign="top">Great image!  Beautifully shot too.  I like that the bulb isn''t perfectly clean like many of similar ilk because it really adds to the old lantern feel that it conveys (to me at least).  I hope this ribbons because it has a wonderful charm about it.</td>', 'Great image!  Beautifully shot too.  I like that the bulb isn''t perfectly clean like many of similar ilk because it really adds to the old lantern feel that it conveys (to me at least).  I hope this ribbons because it has a wonderful charm about it.', '2008-01-02 22:17:52.000000', NULL, 1),
(4355782, 628224, 17771, '<td valign="top">Nice capture of a camp fire.</td>', 'Nice capture of a camp fire.', '2008-01-02 22:49:26.000000', NULL, 1),
(4355787, 628320, 52449, '<td valign="top">I love the star effect on the sun. However, the horizon seems to be not level and the diagonal pole in the composition is distracting.</td>', 'I love the star effect on the sun. However, the horizon seems to be not level and the diagonal pole in the composition is distracting.', '2008-01-02 22:50:55.000000', NULL, 1),
(4355799, 628100, 52449, '<td valign="top">Love the gradient border.</td>', 'Love the gradient border.', '2008-01-02 22:56:28.000000', NULL, 1),
(4355810, 626920, 52449, '<td valign="top">I wish the image was the regulation size of 640 pixels on your width (instead of 500). If so, it would have made this a more dramatic image.</td>', 'I wish the image was the regulation size of 640 pixels on your width (instead of 500). If so, it would have made this a more dramatic image.', '2008-01-02 22:58:43.000000', NULL, 1),
(4355814, 628207, 52449, '<td valign="top">Excellent idea, but the image is a bit soft (out of focus).</td>', 'Excellent idea, but the image is a bit soft (out of focus).', '2008-01-02 23:00:19.000000', NULL, 1),
(4355892, 626746, 87318, '<td valign="top">My focus is drawn to the light spot over the head of the woman to the right.  The knee/pant leg of the woman on the left appears more in focus than the fire, which I think is your real subject.  Contrast of between the background and the scarved heads could be better.  They seem to blend into the background (maybe this is your intent?.  I do like the theme and thought is was a creative setting for the assignment.</td>', 'My focus is drawn to the light spot over the head of the woman to the right.  The knee/pant leg of the woman on the left appears more in focus than the fire, which I think is your real subject.  Contrast of between the background and the scarved heads could be better.  They seem to blend into the background (maybe this is your intent?.  I do like the theme and thought is was a creative setting for the assignment.', '2008-01-02 23:28:11.000000', NULL, 1),
(4355898, 628338, 87318, '<td valign="top">I like it, but think it might have been better pulled off with a darker background to help the flame stand out more.</td>', 'I like it, but think it might have been better pulled off with a darker background to help the flame stand out more.', '2008-01-02 23:29:36.000000', NULL, 1),
(4356109, 628372, 78599, '<td valign="top">I would have liked it better without the child. The flames are very cool:D</td>', 'I would have liked it better without the child. The flames are very cool:D', '2008-01-03 00:31:31.000000', NULL, 1),
(4356185, 628038, 80859, '<td valign="top">great concept, great photo, great title /10</td>', 'great concept, great photo, great title /10', '2008-01-03 01:09:09.000000', NULL, 1),
(4356233, 628312, 88422, '<td valign="top">The reflections in the water are well executed.  Bravo.</td>', 'The reflections in the water are well executed.  Bravo.', '2008-01-03 01:31:54.000000', NULL, 1),
(4356337, 627617, 88486, '<td valign="top">i cant really see any actual fire, but still you know its a picture of a fire. love it</td>', 'i cant really see any actual fire, but still you know its a picture of a fire. love it', '2008-01-03 02:28:52.000000', NULL, 1),
(4356580, 627352, 5364, '<td valign="top">It''s a good idea, but to do it in bright daylight wasn''t a good move. A much darker and less distracting background would have improved this a great deal.</td>', 'It''s a good idea, but to do it in bright daylight wasn''t a good move. A much darker and less distracting background would have improved this a great deal.', '2008-01-03 07:46:31.000000', NULL, 1),
(4356582, 627617, 5364, '<td valign="top">I don''t think you''ve done yourself any favours by making it monochrome - good for photojournalism, not so good for photo competition.</td>', 'I don''t think you''ve done yourself any favours by making it monochrome - good for photojournalism, not so good for photo competition.', '2008-01-03 07:48:28.000000', NULL, 1),
(4356597, 627127, 5364, '<td valign="top">I find the brightness of the sky very distracting</td>', 'I find the brightness of the sky very distracting', '2008-01-03 07:53:50.000000', NULL, 1),
(4356609, 626711, 5364, '<td valign="top">I would have preferred it in colour, and with less empty sky - maybe with the horizon at the top third rather than the middle.</td>', 'I would have preferred it in colour, and with less empty sky - maybe with the horizon at the top third rather than the middle.', '2008-01-03 07:57:35.000000', NULL, 1),
(4356698, 628447, 81382, '<td valign="top">Quite an extreme aspect ratio, which works well here. A bit of post processing perhaps to beef up the blues to complement the firey hues would have balanced out the image overall.</td>', 'Quite an extreme aspect ratio, which works well here. A bit of post processing perhaps to beef up the blues to complement the firey hues would have balanced out the image overall.', '2008-01-03 08:50:55.000000', NULL, 1),
(4356703, 626286, 81382, '<td valign="top">As with a lot of low lit firey entries this week, there is a common theme of sharpness, or lack of it. If oly the wick was a lot sharper then it would complement the blurry fire well and give an added focal point for the eye</td>', 'As with a lot of low lit firey entries this week, there is a common theme of sharpness, or lack of it. If oly the wick was a lot sharper then it would complement the blurry fire well and give an added focal point for the eye', '2008-01-03 08:52:38.000000', NULL, 1),
(4356708, 628019, 81382, '<td valign="top">Such a shame there is an obscuring fence around the fire which rather distracts the eye away from the main subject. Perhaps if you made a clever reference to the fence in the title then it would seem more relevent. e.g Firetrap, Ring of Fire etc...</td>', 'Such a shame there is an obscuring fence around the fire which rather distracts the eye away from the main subject. Perhaps if you made a clever reference to the fence in the title then it would seem more relevent. e.g Firetrap, Ring of Fire etc...', '2008-01-03 08:55:14.000000', NULL, 1),
(4356712, 628208, 81382, '<td valign="top">Almost got the match sharp which is what I''ve been crying out for when commenting on other low lit flame images that dont contain a sharp focal point. Perhaps this just needed a touch much USM after resizing to make it spot on.</td>', 'Almost got the match sharp which is what I''ve been crying out for when commenting on other low lit flame images that dont contain a sharp focal point. Perhaps this just needed a touch much USM after resizing to make it spot on.', '2008-01-03 08:57:05.000000', NULL, 1),
(4356720, 628451, 81382, '<td valign="top">Very dramatic and I''m guessing not staged, which must be the first I''ve voted on in this challenge so thats nice to see. Could perhaps have pushed the constrast higher still with levels or curves to deepen the blacks as there is hardly any detail there anyway on my display and a building silhouette would have been stunning. The tree in the background is a shame.</td>', 'Very dramatic and I''m guessing not staged, which must be the first I''ve voted on in this challenge so thats nice to see. Could perhaps have pushed the constrast higher still with levels or curves to deepen the blacks as there is hardly any detail there anyway on my display and a building silhouette would have been stunning. The tree in the background is a shame.', '2008-01-03 09:00:16.000000', NULL, 1),
(4356796, 628198, 80859, '<td valign="top">the hand seems a little out of focus to me. the background could be improved in some way (maybe some a solid coloured paper attached to the wall?)  some of the fire is lost outside the photo.  my eye is drawn off the photo almost immediately.</td>', 'the hand seems a little out of focus to me. the background could be improved in some way (maybe some a solid coloured paper attached to the wall?)  some of the fire is lost outside the photo.  my eye is drawn off the photo almost immediately.', '2008-01-03 09:18:39.000000', NULL, 1),
(4357442, 628451, 81669, '<td valign="top">Gee. You went to a lot of effort to set this photo up. Where did you find your props? Actually, this is a very powerful, intense photo!</td>', 'Gee. You went to a lot of effort to set this photo up. Where did you find your props? Actually, this is a very powerful, intense photo!', '2008-01-03 13:02:54.000000', NULL, 1),
(4357460, 628181, 81669, '<td valign="top">Very haunting, provocative, classy... and, hey, yes, mesmerizing!</td>', 'Very haunting, provocative, classy... and, hey, yes, mesmerizing!', '2008-01-03 13:08:27.000000', NULL, 1),
(4357478, 628100, 81669, '<td valign="top">Wow! This is... HOT!</td>', 'Wow! This is... HOT!', '2008-01-03 13:16:38.000000', NULL, 1),
(4357492, 626696, 81669, '<td valign="top">Nice! Just... very, very nice. Good concept. Good portrait. Warm smile.</td>', 'Nice! Just... very, very nice. Good concept. Good portrait. Warm smile.', '2008-01-03 13:22:36.000000', NULL, 1),
(4357493, 628326, 81669, '<td valign="top">I like the simplicity of this... lovely colors! A winner!!</td>', 'I like the simplicity of this... lovely colors! A winner!!', '2008-01-03 13:22:45.000000', NULL, 1),
(4357602, 625979, 64568, '<td valign="top">great focus, lovely colours and nice compostion. Best one in th challenge for me, 10</td>', 'great focus, lovely colours and nice compostion. Best one in th challenge for me, 10', '2008-01-03 14:08:01.000000', NULL, 1),
(4357738, 628441, 41802, '<td valign="top">Very nice focus.  I love the colors that you were capture, it really feels hot.  Nice composition.</td>', 'Very nice focus.  I love the colors that you were capture, it really feels hot.  Nice composition.', '2008-01-03 14:48:24.000000', NULL, 1),
(4357739, 627950, 41802, '<td valign="top">Very nice choice of black and white, I like that it really allows the viewer to focus on the letters. Nice job.</td>', 'Very nice choice of black and white, I like that it really allows the viewer to focus on the letters. Nice job.', '2008-01-03 14:48:52.000000', NULL, 1),
(4357740, 628235, 41802, '<td valign="top">Good use of negative space to draw us into the subject.</td>', 'Good use of negative space to draw us into the subject.', '2008-01-03 14:49:08.000000', NULL, 1),
(4357747, 628255, 41802, '<td valign="top">Very cool shot.  I can''t imagine how hard this shot was but I think it might have scored a little higher with me without the swirls at the bottom.  Nice work.</td>', 'Very cool shot.  I can''t imagine how hard this shot was but I think it might have scored a little higher with me without the swirls at the bottom.  Nice work.', '2008-01-03 14:50:06.000000', NULL, 1),
(4357751, 627338, 41802, '<td valign="top">Good focus on the logs.  Nice capture of the smoothness of the flames.</td>', 'Good focus on the logs.  Nice capture of the smoothness of the flames.', '2008-01-03 14:50:33.000000', NULL, 1),
(4357788, 628047, 41802, '<td valign="top">Wow this is pretty cool.  Good timing with the challenge.  Good composition leaving in the fire in the shot.</td>', 'Wow this is pretty cool.  Good timing with the challenge.  Good composition leaving in the fire in the shot.', '2008-01-03 15:01:55.000000', NULL, 1),
(4357790, 627820, 41802, '<td valign="top">Wow having so much black really makes this shot look intense.  Very nice capture.</td>', 'Wow having so much black really makes this shot look intense.  Very nice capture.', '2008-01-03 15:02:19.000000', NULL, 1),
(4357793, 627617, 41802, '<td valign="top">Good job using black and white to keep us focused on the action.  Great night time photography.</td>', 'Good job using black and white to keep us focused on the action.  Great night time photography.', '2008-01-03 15:02:47.000000', NULL, 1),
(4357975, 626746, 56002, '<td valign="top">Nicely done.  Subtle and full of story.</td>', 'Nicely done.  Subtle and full of story.', '2008-01-03 16:09:52.000000', NULL, 1),
(4357980, 626286, 88352, '<td valign="top">Nice composition</td>', 'Nice composition', '2008-01-03 16:10:56.000000', NULL, 1),
