(4359152, 626722, 10084, '<td valign="top">The heating element is the most interesting part of the picture. The little bit of lighting on the bottom either from a flash or other lighting distracts. Darkening the room would really bring more attention to the spiral shape. The contrast of the orange and the black would make it a great abstract.</td>', 'The heating element is the most interesting part of the picture. The little bit of lighting on the bottom either from a flash or other lighting distracts. Darkening the room would really bring more attention to the spiral shape. The contrast of the orange and the black would make it a great abstract.', '2008-01-03 23:30:59.000000', NULL, 1),
(4359162, 626711, 10084, '<td valign="top">Interesting long exposure. Looks like the background is more in focus then the foreground. Zooming in or cropping closer to the industry site make make for a better composition. Possibly too much sky.<br/> <br/>I guess with what you have photograph you can view the city in the background as the important element of the picture and that the power that is being made is for that city.</td>', 'Interesting long exposure. Looks like the background is more in focus then the foreground. Zooming in or cropping closer to the industry site make make for a better composition. Possibly too much sky. I guess with what you have photograph you can view the city in the background as the important element of the picture and that the power that is being made is for that city.', '2008-01-03 23:34:46.000000', NULL, 1),
(4359164, 628454, 64176, '<td valign="top">that''s a nice image!  crisp, colorful and interesting. 8</td>', 'that''s a nice image!  crisp, colorful and interesting. 8', '2008-01-03 23:35:40.000000', NULL, 1),
(4359167, 625979, 10084, '<td valign="top">Very clean photograph. Good use of the dark background to the orange of the flame. Nice sharp image all around. The blue frame works very well with the blue of the smoke.</td>', 'Very clean photograph. Good use of the dark background to the orange of the flame. Nice sharp image all around. The blue frame works very well with the blue of the smoke.', '2008-01-03 23:36:29.000000', NULL, 1),
(4359175, 627928, 10084, '<td valign="top">The two matches that forms an arrow leads eyes toward the flame so the composition works nicely.</td>', 'The two matches that forms an arrow leads eyes toward the flame so the composition works nicely.', '2008-01-03 23:38:03.000000', NULL, 1),
(4359548, 628084, 18207, '<td valign="top">Nice experiment, room to advance. I miss fire.</td>', 'Nice experiment, room to advance. I miss fire.', '2008-01-04 04:51:54.000000', NULL, 1),
(4359550, 626600, 18207, '<td valign="top">Your framing does not add to the image. I don''t know what are you trying to convey here. Sorry, I can''t give it more than 3.</td>', 'Your framing does not add to the image. I don''t know what are you trying to convey here. Sorry, I can''t give it more than 3.', '2008-01-04 04:56:34.000000', NULL, 1),
