(4359565, 628222, 18207, '<td valign="top">I was waiting for a match close-up and it came pretty fast. Nice selection of head color.</td>', 'I was waiting for a match close-up and it came pretty fast. Nice selection of head color.', '2008-01-04 05:12:46.000000', NULL, 1),
(4359568, 626718, 18207, '<td valign="top">Soft and well-composed abstract which needs a proper environment (like a series of similar photos) to show its full potential.</td>', 'Soft and well-composed abstract which needs a proper environment (like a series of similar photos) to show its full potential.', '2008-01-04 05:14:07.000000', NULL, 1),
(4359570, 628208, 18207, '<td valign="top">We all could be sure to get several match shots. Besides the technical skills, the composition could make any of these stand out. In case of this shot, all we got is the flame in the most usual composition. Need something more.</td>', 'We all could be sure to get several match shots. Besides the technical skills, the composition could make any of these stand out. In case of this shot, all we got is the flame in the most usual composition. Need something more.', '2008-01-04 05:16:02.000000', NULL, 1),
(4359571, 627357, 18207, '<td valign="top">It surely has a deep meaning to you. I, as an outsider, can''t really grab that feeling.</td>', 'It surely has a deep meaning to you. I, as an outsider, can''t really grab that feeling.', '2008-01-04 05:17:54.000000', NULL, 1),
(4359572, 626829, 18207, '<td valign="top">The tilted horizont hurts my balance center. I feel it unnecessary. In another composition, it could be more effective, because the idea is good.</td>', 'The tilted horizont hurts my balance center. I feel it unnecessary. In another composition, it could be more effective, because the idea is good.', '2008-01-04 05:19:45.000000', NULL, 1),
(4359574, 627276, 18207, '<td valign="top">Refreshing shot among the flames. Composition is nice, the only thing is that I''d like to see a bit wider DoF.</td>', 'Refreshing shot among the flames. Composition is nice, the only thing is that I''d like to see a bit wider DoF.', '2008-01-04 05:22:00.000000', NULL, 1),
