INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4360409, 628293, 88010, '<td valign="top">I wish the flames were a little clearer. But even so, very nice.</td>', 'I wish the flames were a little clearer. But even so, very nice.', '2008-01-04 13:33:15.000000', NULL, 1),
(4360411, 626025, 88010, '<td valign="top">Nice soft blue glow. well done.</td>', 'Nice soft blue glow. well done.', '2008-01-04 13:33:27.000000', NULL, 1),
(4360412, 628107, 88010, '<td valign="top">I can see onlookers through the window at bottom. Not sure if it''s a real fire or a Hollywood fire, but at any rate, well done.</td>', 'I can see onlookers through the window at bottom. Not sure if it''s a real fire or a Hollywood fire, but at any rate, well done.', '2008-01-04 13:33:44.000000', NULL, 1),
(4360414, 628288, 88010, '<td valign="top">How long before it''s a red hot chilly pepper? Nice colors good idea well thought out. Nice.</td>', 'How long before it''s a red hot chilly pepper? Nice colors good idea well thought out. Nice.', '2008-01-04 13:34:15.000000', NULL, 1),
(4360416, 628451, 88010, '<td valign="top">Nice. Sorry about someones loss, but excellent job of capturing this.</td>', 'Nice. Sorry about someones loss, but excellent job of capturing this.', '2008-01-04 13:34:23.000000', NULL, 1),
(4360417, 626529, 88010, '<td valign="top">Nice job. Good colors. Good focus and it includes fire.</td>', 'Nice job. Good colors. Good focus and it includes fire.', '2008-01-04 13:34:30.000000', NULL, 1),
(4360419, 627928, 88010, '<td valign="top">great imagination. wonderful idea.</td>', 'great imagination. wonderful idea.', '2008-01-04 13:34:49.000000', NULL, 1),
(4360422, 626570, 88010, '<td valign="top">Nice warm thought ad a good exposure. I like that I can see some of the surroundings. Missing on so many shots in this challenge.</td>', 'Nice warm thought ad a good exposure. I like that I can see some of the surroundings. Missing on so many shots in this challenge.', '2008-01-04 13:35:01.000000', NULL, 1),
(4360423, 628326, 88010, '<td valign="top">nice composition and set up.</td>', 'nice composition and set up.', '2008-01-04 13:35:23.000000', NULL, 1),
(4360588, 628281, 56243, '<td valign="top">Nicely done, but too much noise.</td>', 'Nicely done, but too much noise.', '2008-01-04 14:56:01.000000', NULL, 1),
(4360595, 627880, 88385, '<td valign="top">This is in the Top 3, for me.<br/> <br/>The photograph is sound fundamentally... nothing in the image distracts me by being either too soft or too harsh, and that is always difficult with this sort of lighting (at least it is for me). The props are placed nicely, as well... <br/> <br/>The subject is relevant to the contest, but is totally unique from all of the other submissions. That, to me, is what makes a photo a winner - does it fit the criteria without trying too hard? Absolutely.<br/> <br/>Your image works the most for me because it offers a story, it is art. <br/> <br/>Thank you for sharing.</td>', 'This is in the Top 3, for me. The photograph is sound fundamentally... nothing in the image distracts me by being either too soft or too harsh, and that is always difficult with this sort of lighting (at least it is for me). The props are placed nicely, as well...  The subject is relevant to the contest, but is totally unique from all of the other submissions. That, to me, is what makes a photo a winner - does it fit the criteria without trying too hard? Absolutely. Your image works the most for me because it offers a story, it is art.  Thank you for sharing.', '2008-01-04 15:01:10.000000', NULL, 1),
(4360602, 627870, 56243, '<td valign="top">cute idea just really blurry</td>', 'cute idea just really blurry', '2008-01-04 15:03:17.000000', NULL, 1),
(4360614, 627352, 56243, '<td valign="top">Very cool idea.  A bit too bright in a few places.</td>', 'Very cool idea.  A bit too bright in a few places.', '2008-01-04 15:06:27.000000', NULL, 1),
(4360617, 627880, 56243, '<td valign="top">too much noise</td>', 'too much noise', '2008-01-04 15:07:16.000000', NULL, 1),
(4360682, 625871, 88385, '<td valign="top">I love product placement in photography... it may not glow in an artistic light the way other entries due, but these sorts of shots absolutely have a place in photography. As a matter of fact, a more profitable place in photography in the eyes of a commercial artist.<br/> <br/>There are a few things that bug me... focus isn''t quite as sharp as it should be, and the lighting isn''t quite right, either. The tabletop pattern works well, so good choice there, but the candle isn''t working for me - I think removing it from the dish so that nothing takes away from the bottle would work much, much better.<br/> <br/>Thank you for the submission!</td>', 'I love product placement in photography... it may not glow in an artistic light the way other entries due, but these sorts of shots absolutely have a place in photography. As a matter of fact, a more profitable place in photography in the eyes of a commercial artist. There are a few things that bug me... focus isn''t quite as sharp as it should be, and the lighting isn''t quite right, either. The tabletop pattern works well, so good choice there, but the candle isn''t working for me - I think removing it from the dish so that nothing takes away from the bottle would work much, much better. Thank you for the submission!', '2008-01-04 15:27:09.000000', NULL, 1),
