(4364229, 628098, 33446, '<td valign="top">a gold candle....the first one in this challenge</td>', 'a gold candle....the first one in this challenge', '2008-01-05 19:35:47.000000', NULL, 1),
(4364232, 628324, 33446, '<td valign="top">i love the images that the fire makes</td>', 'i love the images that the fire makes', '2008-01-05 19:36:55.000000', NULL, 1),
(4364265, 625979, 22537, '<td valign="top">This is my pick for the blue.  Everything from the composition to the colors and sharpness etc is perfect.  Congrats on the ribbon. ;-)</td>', 'This is my pick for the blue.  Everything from the composition to the colors and sharpness etc is perfect.  Congrats on the ribbon. ;-)', '2008-01-05 19:47:41.000000', NULL, 1),
(4364271, 628312, 22537, '<td valign="top">Gorgeous photo. I gave this an 8 and would have gladly scored higher with the exception that the crop on top and bottom is a smidge too tight IMO. Otherwise, flawless.</td>', 'Gorgeous photo. I gave this an 8 and would have gladly scored higher with the exception that the crop on top and bottom is a smidge too tight IMO. Otherwise, flawless.', '2008-01-05 19:50:06.000000', NULL, 1),
(4364277, 628451, 22537, '<td valign="top">I think you really nailed the flames in this image. Tough to do but you did it.  Good luck!</td>', 'I think you really nailed the flames in this image. Tough to do but you did it.  Good luck!', '2008-01-05 19:51:05.000000', NULL, 1),
(4364280, 627103, 22537, '<td valign="top">I really have no idea what this is but if I did, I''d say the composition is strong and the colors are vibrant. That said, you gat a 7.  Good luck!</td>', 'I really have no idea what this is but if I did, I''d say the composition is strong and the colors are vibrant. That said, you gat a 7.  Good luck!', '2008-01-05 19:52:11.000000', NULL, 1),
(4364288, 627456, 22537, '<td valign="top">I''m a sucker for cool abstracts and zoom photography. Colors are vibrant and the composition is exciting.  Good imaginative effort.  7</td>', 'I''m a sucker for cool abstracts and zoom photography. Colors are vibrant and the composition is exciting.  Good imaginative effort.  7', '2008-01-05 19:54:12.000000', NULL, 1),
(4364291, 627928, 22537, '<td valign="top">It works and well executed.  Good luck!</td>', 'It works and well executed.  Good luck!', '2008-01-05 19:54:45.000000', NULL, 1),
(4364301, 626552, 22537, '<td valign="top">Though this is not the strongest photo technically, it makes me believe he is looking into a volcano ...... with no protective gear and what appear to be trees in the background.  A slightly tighter crop concealing the trees would have nailed it.  Otherwise, looking past that as I really like the feel of the composition, 7.  Good luck.</td>', 'Though this is not the strongest photo technically, it makes me believe he is looking into a volcano ...... with no protective gear and what appear to be trees in the background.  A slightly tighter crop concealing the trees would have nailed it.  Otherwise, looking past that as I really like the feel of the composition, 7.  Good luck.', '2008-01-05 19:58:03.000000', NULL, 1),
(4364305, 628100, 22537, '<td valign="top">Great idea and well delivered. You should de very well. Good luck!</td>', 'Great idea and well delivered. You should de very well. Good luck!', '2008-01-05 19:59:02.000000', NULL, 1),
