(4377709, 625979, 20608, '<td valign="top">go on tim bang that blue in there, nice start to the year</td>', 'go on tim bang that blue in there, nice start to the year', '2008-01-09 12:32:28.000000', NULL, 0),
(4378049, 628293, 83313, '<td valign="top">I really like what you tried to capture here. Very cool. I don''t think it quite worked in your photo, though. The reflections are cut off at the bottom of the frame, and the vertical composition is too centered. If you''d been able to get this at a slightly different angle and height, the improved composition plus a little post processing would really make an attention getting shot.</td>', 'I really like what you tried to capture here. Very cool. I don''t think it quite worked in your photo, though. The reflections are cut off at the bottom of the frame, and the vertical composition is too centered. If you''d been able to get this at a slightly different angle and height, the improved composition plus a little post processing would really make an attention getting shot.', '2008-01-09 14:15:41.000000', NULL, 0),
(4378112, 628037, 66597, '<td valign="top">Sandy, this must have really been something to see! Great photojournalism here. It is really too bad about that rancher''s land, though. I also hope his livestock was not hurt!</td>', 'Sandy, this must have really been something to see! Great photojournalism here. It is really too bad about that rancher''s land, though. I also hope his livestock was not hurt!', '2008-01-09 14:42:56.000000', NULL, 0),
(4378513, 628129, 87968, '<td valign="top">Thanks for all the comments! I''m pretty happy about the ranking as this is my first submission.<br/> <br/>I handheld this shot while watching the fireworks. Yes, it was a bit windy that night. I was pretty lucky to get this shot =)</td>', 'Thanks for all the comments! I''m pretty happy about the ranking as this is my first submission. I handheld this shot while watching the fireworks. Yes, it was a bit windy that night. I was pretty lucky to get this shot =)', '2008-01-09 16:32:34.000000', NULL, 0),
(4378627, 627887, 26492, '<td valign="top">Beautiful light. Great comp on the building. Is this NYC?</td>', 'Beautiful light. Great comp on the building. Is this NYC?', '2008-01-09 17:15:02.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4378635, 627238, 87968, '<td valign="top">I really like the idea of your photo...definitely underrated!<br/>Technically, maybe it''s not the best, but the caption and photo are cute together (if that''s any way to describe photos). The bent match "looking" into the fire is a nice touch.</td>', 'I really like the idea of your photo...definitely underrated!Technically, maybe it''s not the best, but the caption and photo are cute together (if that''s any way to describe photos). The bent match "looking" into the fire is a nice touch.', '2008-01-09 17:16:50.000000', NULL, 0),
