(4379716, 626570, 66384, '<td valign="top">Nice warm Christmas image. I like the composition, the mood, and the sparkle.</td>', 'Nice warm Christmas image. I like the composition, the mood, and the sparkle.', '2008-01-09 22:28:27.000000', NULL, 0),
(4379752, 627916, 67697, '<td valign="top">I think this is underrated.  It is probably a photo that resonates better with parents.  It sure makes me think about things.  Nice job.</td>', 'I think this is underrated.  It is probably a photo that resonates better with parents.  It sure makes me think about things.  Nice job.', '2008-01-09 22:36:08.000000', NULL, 0),
(4379949, 625979, 34938, '<td valign="top">Tiiiiiiiiiiiiiiiiiiiiiiiiiiiiimmmmmmmmmmm!!!!!!!!!!!!!!!!!! Great to share the front page with BLUE''s with you! Great image mate</td>', 'Tiiiiiiiiiiiiiiiiiiiiiiiiiiiiimmmmmmmmmmm!!!!!!!!!!!!!!!!!! Great to share the front page with BLUE''s with you! Great image mate', '2008-01-09 23:29:04.000000', NULL, 0),
(4379975, 628451, 34938, '<td valign="top">So help me understand Laurie...you dressed in black, coloured your face with black shoe polish, headed out to the woods with your matches and petrol and your Lowepro with the camera and lens, lit the fire on some unsuspecting family''s home, and when they ran out you went click, click, click, then ran back into the bushes where you came from. Would that be about right??? AND you made the local papers!!!! It''s amazing what crimes people get away with these days!<br/> <br/>:)<br/> <br/>Well you deserve the ribbon for all that trouble, and the family was insured, right? so they get the new house they always wanted. Well done...everyone wins :)</td>', 'So help me understand Laurie...you dressed in black, coloured your face with black shoe polish, headed out to the woods with your matches and petrol and your Lowepro with the camera and lens, lit the fire on some unsuspecting family''s home, and when they ran out you went click, click, click, then ran back into the bushes where you came from. Would that be about right??? AND you made the local papers!!!! It''s amazing what crimes people get away with these days! :) Well you deserve the ribbon for all that trouble, and the family was insured, right? so they get the new house they always wanted. Well done...everyone wins :)', '2008-01-09 23:33:01.000000', NULL, 0),
(4379989, 628288, 34938, '<td valign="top">Congrats on your first ribbon Eric! Yes, a great way to start the year</td>', 'Congrats on your first ribbon Eric! Yes, a great way to start the year', '2008-01-09 23:35:00.000000', NULL, 0),
